<main class="main" id="assign-subjects"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb" aria-label="Breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Subjects</span><i data-lucide="chevron-right"></i><span aria-current="page">Assign Subjects</span></nav><h1>Add Subjects to a Class</h1><p>Choose the class once, then add all of its subjects in one save.</p></div><a class="btn btn--secondary" href="<?=url('/admin/subjects')?>">View assignments</a></header><form class="module-card" method="post" action="<?= url('/admin/subjects') ?>"><?= csrf_field() ?><header class="module-card__header"><div><h2>Class subjects</h2><p>Use “Add another subject” to build the list before saving.</p></div></header><div class="module-card__body"><div class="module-field"><label for="subject_class">Class <span class="required">*</span></label><select class="module-select" id="subject_class" name="subject_class" required <?= !$classes?'disabled':'' ?>><option value="">Choose a class</option><?php foreach($classes as $class):?><option value="<?= e($class['id']) ?>" <?= (string)old('subject_class')===(string)$class['id']?'selected':'' ?>><?= e($class['name']) ?></option><?php endforeach ?></select><small>You only need to select the class once.</small></div><div class="module-form-grid module-form-grid--two" data-subject-rows><div class="module-field"><label for="subject_name">Subject name <span class="required">*</span></label><input class="module-input" id="subject_name" name="subject_name[]" type="text" placeholder="e.g. Mathematics" required></div><div class="module-field"><label for="subject_marks">Total marks <span class="required">*</span></label><input class="module-input" id="subject_marks" name="subject_marks[]" type="number" value="100" min="1" step="0.01" required></div></div><div class="filter-actions"><button class="btn btn--secondary" type="button" data-demo-action="Add subject row"><i data-lucide="plus"></i>Add another subject</button><button class="btn btn--ghost" type="button" data-demo-action="Remove last subject">Remove last</button></div><?php if(!$classes):?><div class="notice-panel"><i data-lucide="info"></i><span>No classes are available. Create a class first.</span></div><?php endif ?></div><footer class="module-card__footer"><span>Duplicate subjects already assigned to this class will be reported.</span><button class="btn btn--primary" type="submit" <?= !$classes?'disabled':'' ?>><i data-lucide="save"></i>Save all subjects</button></footer></form></div></div></main>
